    // future items, penalize it quadratically.
    if post > 0.0 && post < 10.0 {
        score += (10.0 - post).powi(2) * 5.0;
    }

    // Lookahead logic: if the next item is large, avoid bins that leave just enough space 
    // to be unusable for that item but too small for anything else.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next && post > 0.0 {
            score += (next - post) * 2.5;
        }
    }

    // Dynamic thresholding: as we reach the end of the stream, prioritize 
    // filling existing bins more aggressively to avoid leaving open bins behind.
    // We penalize opening new bins (bin_residual == bin_capacity) more as progress increases.
    if bin_residual == bin_capacity {
        score += 20.0 + (progress * 80.0);
    }

    // Interaction with mean_residual: avoid bins that deviate significantly from the 
    // current average packing density to keep bin states uniform.
    let deviation = (post - mean_residual).abs();
    score += deviation * 0.5;

    // Favor bins that are "last chance" if they are a good fit, 
    // otherwise penalize them to force filling them before they become stranded.
    if fitting_bins_count == 1 && post < 20.0 {
        score -= 15.0;
    }

    score
