    // where no items (min size 10) can fit.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead coupling: If a future item exists, prioritize bins that 
    // leave enough space for it (next_item_size).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward bins that fit the next item perfectly
            score -= (100.0 - (post_residual - next_item_size) as f64) * 0.2;
