            // Penalize bins that block the next item
            score += 30.0;
        }
    }

    // 3. Density balancing: Encourage filling the bin to its capacity to 
    // reduce open_bins_count, weighted by progression.
    let progress = step_index as f64 / total_items as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 5.0;

    // 4. Modulo optimization: Prefer residuals that are multiples of 10,
    // as they are more likely to accommodate standard item distributions.
    if post_residual % 10 != 0 {
        score += 5.0;
    }

    // 5. New bin logic: If this is a new bin (residual == capacity),
    // only choose it if the penalty for fitting into existing bins is extreme.
    if bin_residual == bin_capacity {
        // High base cost for opening a new bin
        score += 45.0;
        // Reduce cost if we have many bins already (to avoid fragmentation)
        score -= (open_bins_count as f64) * 0.5;
    }

    score
