pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;

    // Base score is the post-residual space (Best Fit strategy).
    // We want to minimize wasted space.
    let mut score = post;

    // Penalty for creating "stranded" space that is too small for common item sizes (10-30).
    // If post_residual is small but not zero, it's often wasted.
    if post > 0.0 && post < 15.0 {
        score += 25.0 * (1.0 - (post / 15.0));
    }

    // Lookahead logic: if the next item can fit in the current post_residual,
    // prioritize this bin heavily (negative bias).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0;
        // Further weight by how well the next item fills the remaining space.
        score -= (post_residual - next_item_size) as f64 * 0.5;
    }

    // Heuristic for new bins: Only open a new bin if the current bin is 'bad' 
    // for future items or if we are nearing the end of the stream.
    if bin_residual == bin_capacity {
        // Penalty for opening a new bin is high to encourage filling existing ones.
        // We reduce this penalty if we have many open bins already to prevent fragmentation.
        score += 35.0 - (open_bins_count as f64 * 0.5);

        // As we reach the end of the stream, opening new bins is less penalized 
        // to ensure we don't force bad fits just to save a bin.
        score -= progress * 10.0;
    }

    // If this is the only bin that can fit the item, prioritize it (avoid new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Harmonic bias: favor bins that result in post_residual being a multiple of 10,
    // as these are statistically likely to accommodate future items in many distributions.
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
