    score += post_residual as f64 * 0.5;

    // 2. Lookahead Synergy: If post_residual is close to next_item_size, we reward it
    // to create a "perfect" fit for the future.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward exact or near-exact matches for the next item
