pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best Fit Decreasing logic: Prioritize filling bins tightly (minimize post_residual)
    // 2. Lookahead logic: If post_residual is smaller than next_item_size, we create "stranded" space.
    //    We heavily penalize placements that create a post_residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 50.0 + (next_item_size - post_residual) as f64 * 1.5;
    }

    // 3. New bin thresholding:
    // If we are forced to open a new bin (bin_residual == bin_capacity), 
    // evaluate the cost of wasting space versus the benefit of keeping existing bins "clean".
    if bin_residual == bin_capacity {
        // Only open a new bin if the current mean_residual is very high (we have plenty of space elsewhere)
        // or if we are at the very end of the stream.
        let progress = step_index as f64 / total_items as f64;
        score += mean_residual * 0.8;
        if progress > 0.9 {
            score -= 20.0; // Increasingly willing to open new bins near the end
        }
    } else {
        // 4. Harmonic-style density penalty:
        // Penalize bins that would end up with a residual in the "useless" range (1-9),
        // as most items are >= 10.
        if post_residual < 10 && post_residual > 0 {
            score += 40.0;
        }

        // 5. Fitting count pressure:
        // If this is the last bin that can fit the item, prioritize it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
    }

    // 6. Balance across bins:
    // Penalize bins that deviate significantly from the mean_residual to keep space distributed.
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    score
}
